<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth;
class FinancialHistoryController extends Controller { public function index(Request $request){$user=Auth::user();$q=$user->financialActivities()->with(['walletTransaction.paymentMethod','internalTransfer','actor'])->latest(); if($request->filled('reference'))$q->where('reference',$request->reference); if($request->filled('status'))$q->where('status',$request->status); if($request->filled('direction')&&in_array($request->direction,['credit','debit'],true))$q->where('direction',$request->direction); if($request->filled('event'))$q->where('event_type','like',$request->event.'%'); if($request->filled('date_from'))$q->whereDate('created_at','>=',$request->date_from); if($request->filled('date_to'))$q->whereDate('created_at','<=',$request->date_to); $activities=$q->paginate(30)->withQueryString(); $eventGroups=$user->financialActivities()->selectRaw("SUBSTRING_INDEX(event_type, '.', 1) as event_group")->distinct()->orderBy('event_group')->pluck('event_group'); return view('account.history',compact('activities','eventGroups')); } }
